func BenchmarkPoseidon2Width16(b *testing.B) {
	h := NewPermutation(16, 8, 13)

	var tmp [16]fr.Element
	for i := range tmp {
		tmp[i].MustSetRandom()
	}
	b.ResetTimer()
	for range b.N {
		h.Permutation(tmp[:])
	}
}

